package cn.workbench;
import org.springframework.web.bind.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.csrf.CsrfToken;import jakarta.servlet.http.*;import java.util.*;import java.time.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;
@RestController @RequestMapping("/api/v1/auth") public class Auth {
 @org.springframework.beans.factory.annotation.Autowired Policy policy;
 private final Store db;private final PasswordEncoder passwords;private final Crypto crypto;private final TransactionTemplate tx;
 public Auth(Store db,PasswordEncoder p,Crypto c,PlatformTransactionManager manager){this.db=db;passwords=p;crypto=c;tx=new TransactionTemplate(manager);}
 public static boolean totpRequired(Map<String,Object> scope){return Set.of("ADMIN","GROUP_LEADER","DIVISION_LEADER","COMPANY_LEADER").contains(scope.get("role"));}
 static long uid(HttpServletRequest q){var s=q.getSession(false);if(s==null||s.getAttribute("uid")==null)throw new ApiException(401,"UNAUTHENTICATED","请先登录");return ((Number)s.getAttribute("uid")).longValue();}
 @GetMapping("/csrf") Object csrf(CsrfToken token){return Api.ok(Map.of("token",token.getToken(),"headerName",token.getHeaderName()));}
 @PostMapping("/login") Object login(@RequestBody Map<String,Object>b,HttpServletRequest q){String account=String.valueOf(b.getOrDefault("account",""));var u=db.userByAccount(account);String dummy="$2a$12$W5t0lFVwZrL54v4eETm6neQCRZ8tXrrXJqrVvQ5kqIrBfJ1k6NYIG";boolean correct=passwords.matches(String.valueOf(b.getOrDefault("password","")),u==null?dummy:String.valueOf(u.get("passwordHash")));var now=LocalDateTime.now();if(u!=null&&u.get("lockedUntil") instanceof java.sql.Timestamp t&&t.toLocalDateTime().isAfter(now))throw new ApiException(429,"LOGIN_LOCKED","登录失败，请稍后重试");if(u==null||!correct||!Boolean.TRUE.equals(u.get("enabled"))){if(u!=null){int failures=Jsons.integer(u.get("failedAttempts"))+1;db.incrementFailure(Jsons.number(u.get("id")),now.plusMinutes(30));}throw new ApiException(401,"LOGIN_FAILED","登录失败，请检查凭据");}long id=Jsons.number(u.get("id"));db.failure(id,0,null);var scopes=db.scopes(id);if(scopes.isEmpty())throw ApiException.denied();var old=q.getSession(false);if(old!=null)old.invalidate();var session=q.getSession(true);session.setMaxInactiveInterval(8*3600);session.setAttribute("uid",id);session.setAttribute("sessionVersion",Jsons.integer(u.get("sessionVersion")));session.setAttribute("scopeId",Jsons.number(scopes.getFirst().get("id")));session.setAttribute("totpVerified",false);session.setAttribute("passwordAt",System.currentTimeMillis());if(u.get("totpSecret")!=null&&b.get("totp")!=null)verifyCode(id,String.valueOf(b.get("totp")),session);if(b.get("recoveryCode")!=null)recoverCode(id,String.valueOf(b.get("recoveryCode")),session);return Api.ok(meData(q));}
 @GetMapping("/me") Object me(HttpServletRequest q){return Api.ok(meData(q));}
 Map<String,Object> meData(HttpServletRequest q){long id=uid(q);var u=db.user(id);var scopes=db.scopes(id);var s=db.scope(id,((Number)q.getSession().getAttribute("scopeId")).longValue());if(s==null)throw ApiException.denied();Map<String,Object> r=new LinkedHashMap<>();r.put("id",id);r.put("name",u.get("name"));String account=String.valueOf(u.get("account"));r.put("accountSuffix",account.substring(Math.max(0,account.length()-4)));r.put("role",s.get("role"));r.put("companyId",s.get("companyId"));r.put("deptId",s.get("deptId"));r.put("mustChangePassword",u.get("mustChangePassword"));r.put("totpRequired",totpRequired(s));r.put("totpVerified",Boolean.TRUE.equals(q.getSession().getAttribute("totpVerified")));r.put("totpBound",u.get("totpSecret")!=null);r.put("scopes",scopes);if(q.getSession().getAttribute("delegationId")!=null){var a=policy.actor(q);r.put("role",a.role());r.put("companyId",a.company());r.put("deptId",a.dept());var delegation=policy.changes.delegation(a.delegationId(),false);r.put("delegation",Records.map("id",a.delegationId(),"delegatorId",a.delegatorId(),"companyId",a.company(),"deptId",a.dept(),"permissions",a.delegationPermissions(),"validUntil",delegation.get("validUntil")));}return r;}
 @PostMapping("/context") Object context(@RequestBody Map<String,Object>b,HttpServletRequest q){long id=uid(q);long scope=Jsons.number(b.get("scopeId"));if(db.scope(id,scope)==null)throw ApiException.denied();q.getSession().removeAttribute("delegationId");q.getSession().setAttribute("scopeId",scope);return Api.ok(meData(q));}
 @PostMapping("/logout") Object logout(HttpServletRequest q){var s=q.getSession(false);if(s!=null)s.invalidate();return Api.ok(Map.of());}
 @PostMapping("/change-password") Object change(@RequestBody Map<String,Object>b,HttpServletRequest q){long id=uid(q);var u=db.user(id);if(!passwords.matches(String.valueOf(b.get("oldPassword")),String.valueOf(u.get("passwordHash"))))throw new ApiException(422,"INVALID_PASSWORD","原密码不正确");String n=String.valueOf(b.get("newPassword"));if(n.length()<12||n.length()>72||!n.matches("(?s).*[A-Za-z].*")||!n.matches("(?s).*[0-9].*"))throw new ApiException(422,"WEAK_PASSWORD","新密码需12至72位并包含字母和数字");db.password(id,passwords.encode(n));q.getSession().invalidate();return Api.ok(Map.of("reauthenticate",true));}
 @PostMapping("/totp/setup") Object setup(HttpServletRequest q){long id=uid(q);if(db.user(id).get("totpSecret")!=null&&!Boolean.TRUE.equals(q.getSession().getAttribute("totpVerified")))throw ApiException.denied();freshPassword(q);String s=Totp.secret();q.getSession().setAttribute("pendingTotp",crypto.encrypt(s));return Api.ok(Map.of("secret",s,"otpauthUri","otpauth://totp/TaskWorkbench:"+id+"?secret="+s+"&issuer=TaskWorkbench&digits=6&period=30"));}
 @PostMapping("/totp/confirm") Object confirm(@RequestBody Map<String,Object>b,HttpServletRequest q){long id=uid(q);String encrypted=(String)q.getSession().getAttribute("pendingTotp");if(encrypted==null)throw ApiException.conflict();String s=crypto.decrypt(encrypted);long step=Totp.verify(s,String.valueOf(b.get("code")),Instant.now(),-1);if(step<0)throw new ApiException(422,"INVALID_TOTP","验证码无效");List<String> codes=tx.execute(status->{db.totpSecret(id,encrypted);db.totpStep(id,step);db.revokeRecovery(id);List<String> list=new ArrayList<>();for(int i=0;i<8;i++){String code=UUID.randomUUID().toString();list.add(code);db.addRecovery(id,passwords.encode(code));}return list;});q.getSession().removeAttribute("pendingTotp");q.getSession().setAttribute("totpVerified",true);q.getSession().setAttribute("totpAt",System.currentTimeMillis());return Api.ok(Map.of("recoveryCodes",codes));}
 @PostMapping("/totp/verify") Object verify(@RequestBody Map<String,Object>b,HttpServletRequest q){verifyCode(uid(q),String.valueOf(b.get("code")),q.getSession());return Api.ok(Map.of("totpVerified",true));}
 void verifyCode(long id,String code,HttpSession session){throttleAccount(id);var u=db.user(id);if(u.get("totpSecret")==null)throw new ApiException(422,"TOTP_NOT_BOUND","请先绑定双因素验证");long step=Totp.verify(crypto.decrypt(String.valueOf(u.get("totpSecret"))),code,Instant.now(),Jsons.number(u.get("totpLastStep")));if(step<0||db.totpStep(id,step)!=1){db.incrementTotpFailure(id,LocalDateTime.now().plusMinutes(30));throw new ApiException(422,"INVALID_TOTP","验证码无效或已使用");}db.clearTotpFailures(id);session.setAttribute("totpVerified",true);session.setAttribute("totpAt",System.currentTimeMillis());}
 @PostMapping("/totp/recover") Object recover(@RequestBody Map<String,Object>b,HttpServletRequest q){recoverCode(uid(q),String.valueOf(b.get("recoveryCode")),q.getSession());return Api.ok(Map.of("totpVerified",true));}
 void recoverCode(long id,String code,HttpSession session){throttleAccount(id);for(var c:db.recovery(id))if(passwords.matches(code,String.valueOf(c.get("codeHash")))&&db.consumeRecovery(Jsons.number(c.get("id")))==1){session.setAttribute("totpVerified",true);session.setAttribute("totpAt",System.currentTimeMillis());return;}db.incrementTotpFailure(id,LocalDateTime.now().plusMinutes(30));throw new ApiException(422,"INVALID_RECOVERY","恢复码无效");}
 void freshPassword(HttpServletRequest q){Object at=q.getSession().getAttribute("passwordAt");if(at==null||System.currentTimeMillis()-Jsons.number(at)>5*60*1000)throw new ApiException(403,"FRESH_PASSWORD_REQUIRED","绑定前请重新登录验证密码");}
 void throttleAccount(long id){var user=db.user(id);Object lock=user.get("totpLockedUntil");if(lock!=null&&Records.instant(lock).isAfter(Instant.now()))throw new ApiException(429,"TOTP_LOCKED","验证失败过多，请稍后重试");}
 void throttle(HttpSession session){long now=System.currentTimeMillis();Long until=(Long)session.getAttribute("totpLock");if(until!=null&&until>now)throw new ApiException(429,"TOTP_LOCKED","验证失败过多，请稍后重试");Integer count=(Integer)session.getAttribute("totpAttempts");int n=count==null?1:count+1;session.setAttribute("totpAttempts",n);if(n>=5){session.setAttribute("totpLock",now+30*60*1000);session.setAttribute("totpAttempts",0);}}
}
